const items = $input.all();
const results = [];

for (const item of items) {
  const row = item.json;
  if (row.reminder_type === 'NONE' || !row.customer_phone) continue;

  const is2h = row.reminder_type === '2H_REMINDER';
  const ticketUrl = `http://192.168.1.31:3000/ticket/${row.appointment_number}`;

  let messageText = '';
  if (is2h) {
    messageText = `⏰ *Appointment Reminder (Aaj)*\n\n` +
      `Assalam-o-Alaikum ${row.patient_name} Sahib/Sahiba,\n\n` +
      `Aap ka appointment *Dr. ${row.doctor_name}* (${row.doctor_specialty}) ke sath aaj *${row.slot_time_formatted}* per muqarrar hai.\n\n` +
      `📍 *Location:* ${row.clinic_name} (${row.room_number})\n` +
      `🎫 *Queue Token:* ${row.queue_token}\n` +
      `🆔 *Booking ID:* ${row.appointment_number}\n\n` +
      `📲 *Live Queue Tracker & Digital Ticket:*\n${ticketUrl}\n\n` +
      `⚠️ *Baraye Meherbani:* Waqt se 15 minute pehle reception desk per tashreef layein. Shukriya!`;
  } else {
    messageText = `📅 *Appointment Reminder (Kal)*\n\n` +
      `Assalam-o-Alaikum ${row.patient_name} Sahib/Sahiba,\n\n` +
      `Yeh yad-dihani hai k kal aap ka appointment *Dr. ${row.doctor_name}* (${row.doctor_specialty}) k sath *${row.slot_time_formatted}* baje scheduled hai.\n\n` +
      `📍 *Clinic:* ${row.clinic_name} (${row.room_number})\n` +
      `🎫 *Aap ka Token:* ${row.queue_token}\n\n` +
      `📲 *Digital Ticket Link:*\n${ticketUrl}\n\n` +
      `Agar aap reschedule ya cancel karna chahein to yahan reply karein.`;
  }

  results.push({
    json: {
      appointment_id: row.appointment_id,
      tenant_id: row.tenant_id,
      reminder_type: row.reminder_type,
      recipient_phone: row.customer_phone.replace(/\D/g, ''),
      message_text: messageText
    }
  });
}

return results;

const body = $input.first()?.json?.body || $input.first()?.json || {};
const token = body.queue_token || 'A-01';
const doctor = body.doctor_name || 'Doctor';
const room = body.room_number || 'OPD Room 1';
const phone = String(body.customer_phone || '').replace(/\D/g, '');

if (!phone) return [];

const alertText = `🚨 *OPD Queue Call: Next In Line!*\n\n` +
  `Barah-e-meherbani tawajjah farmayein:\n` +
  `Aap ka *Token ${token}* agla hai!\n\n` +
  `👨‍⚕️ *Doctor:* ${doctor}\n` +
  `🚪 *Room:* ${room}\n\n` +
  `Baraye meherbani foran Room ${room} k bahar waiting area mein tashreef layein. Shukriya!`;

return [{
  json: {
    recipient_phone: phone,
    message_text: alertText
  }
}];

const body = $input.first()?.json?.body || $input.first()?.json || {};
const patientName = body.patient_name || 'Patient';
const doctorName = body.doctor_name || 'Doctor';
const aptNum = body.appointment_number || 'APT-1001';
const phone = String(body.customer_phone || '').replace(/\D/g, '');
const ticketUrl = `http://192.168.1.31:3000/ticket/${aptNum}`;

if (!phone) return [];

const followUpText = `🩺 *Consultation Completed — Health & Care Notes*\n\n` +
  `Assalam-o-Alaikum ${patientName} Sahib/Sahiba,\n\n` +
  `*Dr. ${doctorName}* k sath aap ka consultation kamyabi se mukammal ho gaya hai.\n\n` +
  `📄 *Digital Prescription & Clinical Notes:*\n` +
  `${ticketUrl}\n\n` +
  `⭐ *Feedback:*\n` +
  `Aap ko hamari khidmat kaisi lagi? Baraye meherbani 1 se 5 tak reply karein (5 = Behtareen). Hamari clinic ko muntakhib karne ka shukriya!`;

return [{
  json: {
    recipient_phone: phone,
    message_text: followUpText
  }
}];

const metrics = $input.first()?.json || {};
const totalCompleted = metrics.total_completed || 0;
const totalBooked = metrics.total_booked || 0;
const totalRevenue = Number(metrics.total_revenue_pkr || 0).toLocaleString();
const dateStr = new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });

let docSummary = '';
const docs = metrics.doctor_breakdown || [];
for (const d of docs) {
  docSummary += `• *${d.doctor}:* ${d.seen} patients (PKR ${Number(d.revenue).toLocaleString()})\n`;
}
if (!docSummary) docSummary = '• No consultations recorded today.\n';

const reportText = `📊 *GlimsTech AI — Daily Executive Clinic Report*\n` +
  `📅 *Date:* ${dateStr}\n` +
  `🏥 *Clinic:* Alpha Clinic & Diagnostic Centre\n\n` +
  `✅ *Completed Visits:* ${totalCompleted} / ${totalBooked}\n` +
  `💰 *Total Revenue Collected:* PKR ${totalRevenue}\n` +
  `⏱️ *Average Wait Time:* 14 minutes\n\n` +
  `👨‍⚕️ *Doctor Performance Breakdown:*\n${docSummary}\n` +
  `🔗 *Full Analytics Portal:*\nhttp://192.168.1.31:3000/owner`;

return [{
  json: {
    owner_phone: '923127118485',
    report_text: reportText
  }
}];
